WITH src AS (SELECT * FROM departments WHERE dept_name <> 'Sales'), DepartmentsStats AS (SELECT CASE WHEN budget >= 3305000 THEN 'high' WHEN budget >= 804000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(budget) AS budget_count, COUNT(*) AS row_count FROM src GROUP BY CASE WHEN budget >= 3305000 THEN 'high' WHEN budget >= 804000 THEN 'mid' ELSE 'low' END) SELECT budget_bucket, budget_count, row_count FROM DepartmentsStats
